'use strict';

// MODULES //

var bench = require( '@stdlib/bench' );
var format = require( '@stdlib/string/format' );
var pkg = require( './../package.json' ).name;
var formatTokens = require( './../lib' );


// MAIN //

bench( format( '%s:shallow', pkg ), function benchmark( b ) {
	var out;
	var i;

	b.tic();
	for ( i = 0; i < b.iterations; i++ ) {
		out = formatTokens( [ 'foo', 'bar' ] );
		if ( typeof out !== 'string' ) {
			b.fail( 'should return a string' );
		}
	}
	b.toc();
	if ( out !== '/foo/bar' ) {
		b.fail( 'should return expected value' );
	}
	b.pass( 'benchmark finished' );
	b.end();
});

bench( format( '%s:escaped', pkg ), function benchmark( b ) {
	var out;
	var i;

	b.tic();
	for ( i = 0; i < b.iterations; i++ ) {
		out = formatTokens( [ 'a/b', 'c~d', 'foo', '0' ] );
		if ( typeof out !== 'string' ) {
			b.fail( 'should return a string' );
		}
	}
	b.toc();
	if ( out !== '/a~1b/c~0d/foo/0' ) {
		b.fail( 'should return expected value' );
	}
	b.pass( 'benchmark finished' );
	b.end();
});

bench( format( '%s:deep', pkg ), function benchmark( b ) {
	var out;
	var i;

	b.tic();
	for ( i = 0; i < b.iterations; i++ ) {
		out = formatTokens( [ 'a', 'b', 'c', 'd', 'e', 'f', 'g', 'h' ] );
		if ( typeof out !== 'string' ) {
			b.fail( 'should return a string' );
		}
	}
	b.toc();
	if ( out !== '/a/b/c/d/e/f/g/h' ) {
		b.fail( 'should return expected value' );
	}
	b.pass( 'benchmark finished' );
	b.end();
});

bench( format( '%s:root', pkg ), function benchmark( b ) {
	var out;
	var i;

	b.tic();
	for ( i = 0; i < b.iterations; i++ ) {
		out = formatTokens( [] );
		if ( typeof out !== 'string' ) {
			b.fail( 'should return a string' );
		}
	}
	b.toc();
	if ( out !== '' ) {
		b.fail( 'should return empty string' );
	}
	b.pass( 'benchmark finished' );
	b.end();
});
